function storyCharacterQuestDetail(name){dlgNext=null;M.style.display='flex';M.style.background='';M.innerHTML='<h1>'+name.toUpperCase()+'</h1><small>Ordre des transformations · gagne le chapitre indiqué avec ce personnage pour débloquer la forme.</small>';const grid=document.createElement('div');grid.id='storyQuestGrid';for(const q of FORM_QUESTS.filter(x=>x.character===name)){const unlocked=Number(SS().forms[name]||0)>=q.index,c=chapterById(q.chapter),available=c&&chOpen(c),card=document.createElement('section');card.className='story-quest-card';const info=document.createElement('div');info.style.cssText='font-size:13px;line-height:1.6;padding:4px 2px';info.innerHTML='<b>'+q.index+'. '+q.name+'</b><br>'+(unlocked?'✓ Transformation déjà débloquée':'🔒 Transformation à débloquer')+'<br>Chapitre : '+(c?c.t:q.chapter)+'<br>'+(c?(available?'Chapitre accessible':'Chapitre encore verrouillé'):'Chapitre introuvable');card.appendChild(info);if(!unlocked&&available)card.appendChild(btn('JOUER CE CHAPITRE',()=>playCh(c)));grid.appendChild(card)}M.appendChild(grid);M.appendChild(btn('← Personnages',storyQuestsMenu));M.appendChild(btn('← Retour à l’histoire',storyMenu))}
function dialogue(L,done){let i=0;const A=AR[(curCh&&curCh.ar)||0];const show=()=>{if(i>=L.length){dlgNext=null;M.style.background='';done();return}const hero=CH[cfg.p1]?.n||'Goku',dynamic=curCh&&!curCh.scene&&curCh.players?.includes(hero)&&hero!=='Goku',w0=L[i][0],t0=L[i][1],w=dynamic&&w0==='Goku'?hero:w0,t=dynamic?t0.replace(/\bGoku\b/g,hero):t0,ch=CH.find(x=>x.n===w),col=ch?(ch.fm[0].hair==='#000'?ch.fm[0].au:ch.fm[0].hair):w==='Narration'?'#ccd':w==='Roi Kaï'?'#fd6':w==='Piccolo'?'#6fbf3f':'#8cf';M.style.display='flex';M.style.background='linear-gradient(#0009,#0009),linear-gradient(180deg,'+A[1][0]+','+A[1][1]+')';M.innerHTML='';const b=document.createElement('div');b.style.cssText='width:min(92%,640px);background:#000c;border:2px solid '+col+';padding:14px;text-align:left;border-radius:6px';b.innerHTML='<div style="display:flex;gap:12px;align-items:center"><div style="min-width:54px;height:54px;border-radius:50%;background:'+col+';display:flex;align-items:center;justify-content:center;font:900 26px sans-serif;color:#000">'+w[0]+'</div><div><b style="color:'+col+'">'+w+'</b><div style="margin-top:6px;font-size:16px">'+t+'</div></div></div>';M.appendChild(b);M.appendChild(row([btn('Suivant \u25b6',()=>{i++;show()}),btn('Passer',()=>{i=L.length;show()})]));dlgNext=()=>{i++;show()}};show()}
addEventListener('keydown',e=>{if(dlgNext&&(e.code==='Enter'||e.code==='Space')){e.preventDefault();dlgNext()}});
function reward(c,st,ok){const S=SS(),old=S.done[c.id],first=!old,diff=Math.max(0,Math.min(2,Number(c.df)||0)),chapterXP=Math.max(20,Math.min(500,Number(c.xp)||[80,130,190][diff])),xp=first?Math.round(chapterXP*(st===2?1.15:1)):Math.max(5,Math.round(chapterXP*.15));sv.xp+=xp;if(!c.scene)sv.storyClears=(Number(sv.storyClears)||0)+1;S.done[c.id]={s:Math.max(st,(old||{}).s||0),clears:((old||{}).clears||0)+1};const campaignChapters=SAGAS.flatMap(sg=>sg.ch).filter(ch=>!ch.scene);const campaignComplete=campaignChapters.length>0&&campaignChapters.every(ch=>ch.id===c.id||!!S.done[ch.id]);let bonus=0;if(first&&campaignComplete&&!sv.storyCampaignBonus){bonus=200000;sv.xp+=bonus;sv.storyCampaignBonus=1}const relic=RELICS.find(x=>x.chapter===c.id);if(first&&relic&&!sv.items.includes(relic.id)){sv.items.push(relic.id);sv.newItem=relic.id}if(c.fl)for(const k of c.fl)S.fl[k]=1;const earned=[];for(const q of FORM_QUESTS){if(q.chapter===c.id&&CH[cfg.p1]?.n===q.character){S.forms[q.character]=Math.max(Number(S.forms[q.character])||0,q.index);earned.push(q.name)}}save();return '+'+xp+' XP'+(bonus?' · BONUS FIN DE CAMPAGNE : +'+bonus+' XP (niveau 40+)':'')+(first?' (première victoire)':' (rejoué : récompense réduite)')+(c.rw&&first?' · '+c.rw:'')+(c.ob?' · Objectif réussi':'')+(earned.length?' · Transformation débloquée : '+earned.join(', '):'')}
function launchStoryDialogue(c){dialogue(c.pre||[],()=>{if(c.scene)storyMenu(reward(c,1,true));else startStory(c)})}
function chooseStoryHero(c){let names=(c.chapterPlayers||c.players||STORY_ROSTERS[SAGAS.find(s=>s.ch.includes(c))?.id]||['Goku']).filter(n=>CH.some(x=>x.n===n)&&n!==c.en);if(!c.chapterPlayers&&c.id.startsWith('s2'))names=['Goku','Vegeta','Piccolo','Krillin'].filter(n=>CH.some(x=>x.n===n)&&n!==c.en);if(!c.chapterPlayers&&c.id.startsWith('db'))names=['Goku','Yamcha','Krillin','Tenshinhan','Muten Roshi','Piccolo'].filter(n=>CH.some(x=>x.n===n)&&n!==c.en);if(!c.chapterPlayers&&c.id.startsWith('cell'))names=['Goku','Vegeta','Trunks','Gohan','Piccolo','Android 16','Android 17','Android 18'].filter(n=>CH.some(x=>x.n===n)&&n!==c.en);if(!c.chapterPlayers&&c.id.startsWith('buu'))names=['Goku','Vegeta','Gohan','Gotenks','Piccolo','Majin Buu'].filter(n=>CH.some(x=>x.n===n)&&n!==c.en);if(!names.length)names=CH.map(x=>x.n).filter(n=>n!==c.en);const score=n=>{const q=CH.find(x=>x.n===n),st=q.st||{};return (st.fo||35)*.2+(st.vi||35)*.13+(st.in||35)*.17+(st.du||35)*.15+(st.en||35)*.12+(st.ed||35)*.08+(st.ki||35)*.08+(st.te||35)*.07};const best=names.slice().sort((a,b)=>score(b)-score(a))[0]||'Goku',unlockQuests=FORM_QUESTS.filter(q=>q.chapter===c.id&&names.includes(q.character)&&Number(SS().forms?.[q.character]||0)<q.index);M.style.display='flex';M.style.background='';M.innerHTML='<h1>CHOISIS TON COMBATTANT</h1><small>'+c.t+'</small><small>Difficulté : '+(['Facile','Normale','Difficile'][Math.max(0,Math.min(2,c.df||0))])+' · Récompense : '+[50,100,150][Math.max(0,Math.min(2,c.df||0))]+' XP</small><small style="color:#ffd66b">Condition : '+(c.ob?.txt||'Remporter le combat')+'</small>';if(unlockQuests.length){const unlock=document.createElement('div');unlock.style.cssText='width:min(94%,760px);padding:10px 14px;border:1px solid #62e6a5;border-radius:12px;background:linear-gradient(100deg,#103b2c,#111b34);color:#aaffd1;font-weight:800;box-sizing:border-box';unlock.textContent=unlockQuests.length===1?'★ TRANSFORMATION À GAGNER : joue '+unlockQuests[0].character+' pour débloquer '+unlockQuests[0].name+' !':'★ TRANSFORMATIONS À GAGNER : '+unlockQuests.map(q=>q.name+' avec '+q.character).join(' · ')+'. Choisis le personnage correspondant pour la débloquer.';M.appendChild(unlock)}const tip=document.createElement('div');tip.style.cssText='width:min(94%,760px);padding:9px 14px;border:1px solid #f5c75e;border-radius:12px;background:linear-gradient(100deg,#3a2b0d,#111b34);color:#ffe18a;font-weight:800;box-sizing:border-box';tip.textContent='★ CONSEIL POUR CE CHAPITRE : '+best+' — meilleur équilibre de statistiques parmi les combattants disponibles';M.appendChild(tip);const grid=document.createElement('div');grid.style.cssText='width:min(96%,820px);max-height:54vh;overflow:auto;display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:10px;padding:8px';names.forEach(n=>{const i=CH.findIndex(x=>x.n===n),q=CH[i],st=q.st||{},quests=unlockQuests.filter(x=>x.character===n),card=document.createElement('button');card.className=cfg.p1===i?'on':'';card.style.cssText='display:flex;flex-direction:column;align-items:center;gap:5px;padding:10px;border:1px solid '+(quests.length?'#62e6a5':n===best?'#f5c75e':'#385477')+';border-radius:13px;background:linear-gradient(155deg,#1c3154,#090f20);color:#fff;min-height:130px;';card.appendChild(portrait(i));const nm=document.createElement('b');nm.textContent=n;card.appendChild(nm);const stats=document.createElement('small');stats.textContent='FOR '+(st.fo||'-')+' · VIT '+(st.vi||'-')+' · TEC '+(st.te||'-');card.appendChild(stats);if(quests.length){const tag=document.createElement('small');tag.textContent='★ TRANSFORMATION À DÉBLOQUER : '+quests.map(x=>x.name).join(', ');tag.style.cssText='color:#aaffd1;font-weight:900';card.appendChild(tag)}else if(n===best){const tag=document.createElement('small');tag.textContent='★ CONSEILLÉ';tag.style.cssText='color:#ffdc78;font-weight:900';card.appendChild(tag)}card.onclick=()=>{cfg.p1=i;launchStoryDialogue(c)};grid.appendChild(card)});M.appendChild(grid);M.appendChild(btn('← Retour aux chapitres',storyMenu))}
function playCh(c){curCh=c;if(c.scene){launchStoryDialogue(c);return}chooseStoryHero(c)}
function storyEnemyIndex(c){const aliases={Raditz:'Goku',Nappa:'Vegeta',Ginyu:'Freezer',Yamcha:'Goku',Tenshinhan:'Piccolo','Muten Roshi':'Goku',Glorio:'Goku',Tamagami:'Piccolo',Gomah:'Piccolo','Xeno Goku':'Goku',Cumber:'Broly',Hearts:'Goku','Baby Vegeta':'Vegeta','Omega Shenron':'Cell',Pan:'Gohan',Uub:'Goku',Shallot:'Goku','Zamasu fusionné':'Goku',Kefla:'Vegeta',Toppo:'Jiren',Dyspo:'Jiren','Android 16':'Cell','Android 17':'Piccolo','Android 18':'Piccolo',Dabura:'Cell'};let i=CH.findIndex(x=>x.n===c.en);if(i<0)i=CH.findIndex(x=>x.n===(aliases[c.en]||'Goku'));if(i<0)i=CH.findIndex(x=>x.n==='Goku');return i}
function startStory(c){
 curCh=c;cfg.mode='story';
 const allowed=(c.chapterPlayers||c.players||STORY_ROSTERS[SAGAS.find(s=>s.ch.includes(c))?.id]||['Goku']).filter(n=>CH.some(x=>x.n===n)&&n!==c.en);
 if(!allowed.length)allowed.push(...CH.map(x=>x.n).filter(n=>n!==c.en).slice(0,1));
 if(!CH[cfg.p1]||!allowed.includes(CH[cfg.p1].n))cfg.p1=CH.findIndex(x=>x.n===allowed[0]);
 cfg.p2=storyEnemyIndex(c);cfg.ar=c.ar;cfg.diff=c.df;stage=0;start();
 const fighterName=G.a.c.n,unlocked=storyFormMax(fighterName),whitelist=c.formWhitelist?.[fighterName];
 if(Array.isArray(whitelist)){
  const originalForms=G.a.c.fm,indices=whitelist.filter(index=>index===0||index<=unlocked),selected=indices.filter(index=>originalForms[index]);
  if(!selected.includes(0))selected.unshift(0);
  G.a.c=Object.assign({},G.a.c,{fm:selected.map(index=>originalForms[index])});
  G.a.mf=G.a.c.fm.length-1;
 }else{
  const chapterCap=Number(c.formCaps?.[fighterName]);
  G.a.mf=Number.isFinite(chapterCap)?Math.min(unlocked,chapterCap):unlocked;
 }
 G.b.mf=c.emf||0;
 if(!SS().fl.kk)G.a.nokk=1;
 if(c.ob)G.ann={t:200,s:c.ob.txt,c:'#fd6'};
}
function storyObjectiveCheck(ob,g){if(!ob)return true;const tests=ob.all||[ob];return tests.every(o=>{if(o.k==='hp')return g.a.hp>=g.a.mhp*o.v;if(o.k==='time')return g.time>=o.v;if(o.k==='ki')return g.a.ki>=o.v;if(o.k==='nohit')return g.a.hp>=g.a.mhp*0.8;if(o.k==='form')return (g.a.mf||0)>0;if(o.k==='noform')return (g.a.mf||0)===0;return false})}
function storyEnd(g){const c=curCh,w=g.win===g.a;if(!c)return;if(!w){g.sr={w:false,st:0,txt:'Le combat est perdu.'};return}if(!storyObjectiveCheck(c.ob,g)){g.sr={w:false,st:0,objectiveFail:true,txt:'Tu as gagné le duel, mais la condition obligatoire n’est pas remplie : '+(c.ob?.txt||'objectif du chapitre')+'.'};return}const st=c.ob?2:1;g.sr={w:true,st,txt:reward(c,st,true)}}
function storyAfter(g){const r=g.sr||{w:false},c=curCh;if(r.w){M.style.display='flex';M.innerHTML='<h1>VICTOIRE</h1><small>'+'★'.repeat(r.st)+' — '+r.txt+'</small>';M.appendChild(btn('Continuer',()=>dialogue(c.post||[],()=>storyMenu(r.txt))))}else{M.style.display='flex';M.innerHTML='<h1>'+(r.objectiveFail?'OBJECTIF NON REMPLI':'DÉFAITE')+'</h1><small>'+(r.txt||'Réessaie : change de tactique (garde, esquive, transformation).')+'</small>';M.appendChild(row([btn('Réessayer',()=>startStory(c)),btn('Changer de personnage',()=>chooseStoryHero(c)),btn('Menu histoire',()=>storyMenu())]))}}
